              "qid": "M51-3-1",
              "title": "1. 从第 5 位先向右 3 位再向左 5 位",
              "prompt": "9 位同学站在从左往右编号为 1 到 9 号的位子上。小刚原本站在第 5 号位，他先按口令<strong>向右移动 3 格</strong>，接着再<strong>向左移动 5 格</strong>。现在小刚站在从左数第几位？",
              "tip": "【审题金钥匙】横排排队位置左右移动规律（左为 1，右为 9）：向右移动会让数字变大（加法 5 + 3 = 8 号）；再向左移动会让数字变小（减法 8 - 5 = 3 号）。所以小刚最终站在从左数第 3 位！",
              "visual": "<div class=\"w-full p-2.5 bg-indigo-50/70 border-indigo-200 border rounded-xl flex justify-center\"><svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 460 145\" role=\"img\" aria-label=\"1到9号位置从左到右，小刚在第5位，先向右移动3位，再向左移动5位\" class=\"w-full max-w-[460px] h-auto block mx-auto font-sans\">\n              <rect x=\"8\" y=\"8\" width=\"444\" height=\"129\" rx=\"14\" fill=\"#eef2ff\" stroke=\"#a5b4fc\" stroke-width=\"1.5\"/>\n              <text x=\"230\" y=\"26\" text-anchor=\"middle\" font-size=\"12\" font-weight=\"bold\" fill=\"#3730a3\">左 ➔ 右依次编号（小刚原本在第 5 号）</text>\n              \n                  <circle cx=\"42\" cy=\"64\" r=\"16\" fill=\"#ffffff\" stroke=\"#6366f1\" stroke-width=\"1.5\"/>\n                  <text x=\"42\" y=\"69\" text-anchor=\"middle\" font-size=\"13.5\" font-weight=\"bold\" fill=\"#312e81\">1</text>\n                  \n                \n                  <circle cx=\"89\" cy=\"64\" r=\"16\" fill=\"#ffffff\" stroke=\"#6366f1\" stroke-width=\"1.5\"/>\n                  <text x=\"89\" y=\"69\" text-anchor=\"middle\" font-size=\"13.5\" font-weight=\"bold\" fill=\"#312e81\">2</text>\n                  \n                \n                  <circle cx=\"136\" cy=\"64\" r=\"16\" fill=\"#ffffff\" stroke=\"#6366f1\" stroke-width=\"1.5\"/>\n                  <text x=\"136\" y=\"69\" text-anchor=\"middle\" font-size=\"13.5\" font-weight=\"bold\" fill=\"#312e81\">3</text>\n                  \n                \n                  <circle cx=\"183\" cy=\"64\" r=\"16\" fill=\"#ffffff\" stroke=\"#6366f1\" stroke-width=\"1.5\"/>\n                  <text x=\"183\" y=\"69\" text-anchor=\"middle\" font-size=\"13.5\" font-weight=\"bold\" fill=\"#312e81\">4</text>\n                  \n                \n                  <circle cx=\"230\" cy=\"64\" r=\"16\" fill=\"#fef3c7\" stroke=\"#d97706\" stroke-width=\"2.4\"/>\n                  <text x=\"230\" y=\"69\" text-anchor=\"middle\" font-size=\"13.5\" font-weight=\"bold\" fill=\"#92400e\">5</text>\n                  <text x=\"230\" y=\"94\" text-anchor=\"middle\" font-size=\"11\" font-weight=\"bold\" fill=\"#b45309\">★ 原位置</text>\n                \n                  <circle cx=\"277\" cy=\"64\" r=\"16\" fill=\"#ffffff\" stroke=\"#6366f1\" stroke-width=\"1.5\"/>\n                  <text x=\"277\" y=\"69\" text-anchor=\"middle\" font-size=\"13.5\" font-weight=\"bold\" fill=\"#312e81\">6</text>\n                  \n                \n                  <circle cx=\"324\" cy=\"64\" r=\"16\" fill=\"#ffffff\" stroke=\"#6366f1\" stroke-width=\"1.5\"/>\n                  <text x=\"324\" y=\"69\" text-anchor=\"middle\" font-size=\"13.5\" font-weight=\"bold\" fill=\"#312e81\">7</text>\n                  \n                \n                  <circle cx=\"371\" cy=\"64\" r=\"16\" fill=\"#ffffff\" stroke=\"#6366f1\" stroke-width=\"1.5\"/>\n                  <text x=\"371\" y=\"69\" text-anchor=\"middle\" font-size=\"13.5\" font-weight=\"bold\" fill=\"#312e81\">8</text>\n                  \n                \n                  <circle cx=\"418\" cy=\"64\" r=\"16\" fill=\"#ffffff\" stroke=\"#6366f1\" stroke-width=\"1.5\"/>\n                  <text x=\"418\" y=\"69\" text-anchor=\"middle\" font-size=\"13.5\" font-weight=\"bold\" fill=\"#312e81\">9</text>\n                  \n                \n              <rect x=\"34\" y=\"106\" width=\"182\" height=\"24\" rx=\"7\" fill=\"#ffffff\" stroke=\"#818cf8\" stroke-width=\"1.3\"/>\n              <text x=\"125\" y=\"123\" text-anchor=\"middle\" font-size=\"12\" font-weight=\"bold\" fill=\"#1e1b4b\">① 先向右移动 3 格（→ 3）</text>\n              <rect x=\"244\" y=\"106\" width=\"182\" height=\"24\" rx=\"7\" fill=\"#ffffff\" stroke=\"#818cf8\" stroke-width=\"1.3\"/>\n              <text x=\"335\" y=\"123\" text-anchor=\"middle\" font-size=\"12\" font-weight=\"bold\" fill=\"#1e1b4b\">② 再向左移动 5 格（← 5）</text>\n            </svg></div>",
