              "tip": "【审题金钥匙】按动态变化排顺序：① 开始名次：1兔、2猴、3鹿、4羊；② 小羊从第 4 超过前面 2 位（超过小鹿和小猴），变成：1兔、2羊、3猴、4鹿；③ 小鹿再反超小猴，最终：1兔、2羊、3鹿、4猴！所以第 2 名是“小羊”！",
